### Problem Description

We need to iterate a dataframe without implicitly changing the data type

### Feature Description

Add new method to the dataframe. 

```python
def iterdict(self) -> Generator[tuple[int, dict], None, None]:
    """Iterate over rows of a dataframe in a manner that preserves data types"""
    columns = df.columns.tolist()
    for i, elements in enumerate(zip(*(df[c].to_numpy() for c in columns))):
        yield i, dict(zip(columns, elements))
```

Test
```python
import numpy as np
import pandas as pd


def test_type_preservation():
    n = 100
    rng = np.random.default_rng(0)
    df = pd.DataFrame(
        {
            **{
                str(d).split("'")[1].split(".")[-1]: rng.integers(np.iinfo(d).min, np.iinfo(d).max, n, dtype=d)
                for d in (np.uint8, np.uint64, np.int32, np.int64)
            },
            **{
                str(d).split("'")[1].split(".")[-1]: rng.uniform(np.finfo(d).min, np.finfo(d).max, n).astype(d)
                for d in (np.float16, np.float32)
            },
        },
    )
    types = {c: df[c].dtype for c in df.columns}
    for _, row in df.iterdict():
        for c in df.columns:
            assert type(row[c]) == types[c], f"{c}: {type(row[c])=} != {types[c]=}"
